import{_ as i,o as n,c as s,ah as r}from"./chunks/framework.BsNNkeaH.js";const p=JSON.parse('{"title":"Discipline et conseils","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/vie-scolaire/discipline-et-conseils.md","filePath":"src/guide/vie-scolaire/discipline-et-conseils.md"}'),t={name:"guide/vie-scolaire/discipline-et-conseils.md"};function o(l,e,a,c,u,d){return n(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="discipline-et-conseils" tabindex="-1">Discipline et conseils <a class="header-anchor" href="#discipline-et-conseils" aria-label="Permalink to &quot;Discipline et conseils&quot;">​</a></h1><p>Cette page couvre l&#39;enregistrement des incidents disciplinaires et, lorsqu&#39;un incident le justifie, la convocation puis la décision d&#39;un conseil de discipline.</p><h2 id="enregistrer-un-incident-disciplinaire" tabindex="-1">Enregistrer un incident disciplinaire <a class="header-anchor" href="#enregistrer-un-incident-disciplinaire" aria-label="Permalink to &quot;Enregistrer un incident disciplinaire&quot;">​</a></h2><ol><li>Ouvrez <strong>Vie scolaire → Incidents disciplinaires</strong>, puis cliquez sur <strong>Nouvel incident</strong>.</li><li>Choisissez l&#39;<strong>Élève</strong> concerné et, si pertinent, sa <strong>Classe</strong> (laissez vide s&#39;il n&#39;y a pas de classe spécifique à préciser).</li><li>Renseignez la <strong>Date</strong> de l&#39;incident et sa <strong>Gravité</strong> : <strong>Mineure</strong>, <strong>Majeure</strong> ou <strong>Grave</strong>.</li><li>Décrivez l&#39;incident dans <strong>Description</strong> (obligatoire) et, si une sanction a déjà été appliquée sur le moment, notez-la dans <strong>Sanction</strong>.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>La liste des incidents se filtre par nom d&#39;élève, par classe et par gravité. Depuis cette liste, <strong>Modifier</strong> rouvre l&#39;incident et <strong>Supprimer</strong> l&#39;efface définitivement après confirmation — action irréversible.</p><h2 id="convoquer-et-gerer-un-conseil-de-discipline" tabindex="-1">Convoquer et gérer un conseil de discipline <a class="header-anchor" href="#convoquer-et-gerer-un-conseil-de-discipline" aria-label="Permalink to &quot;Convoquer et gérer un conseil de discipline&quot;">​</a></h2><p>Un conseil de discipline peut être convoqué à partir d&#39;un incident existant ou de façon autonome.</p><ol><li>Depuis la liste des <strong>Incidents disciplinaires</strong>, cliquez sur <strong>Convoquer un conseil</strong> sur la ligne de l&#39;incident concerné (ou ouvrez directement <strong>Vie scolaire → Conseils de discipline</strong> puis <strong>Nouveau conseil</strong> pour partir d&#39;une page vierge).</li><li>Choisissez l&#39;<strong>Élève</strong>, sa <strong>Classe</strong> le cas échéant, et l&#39;<strong>Incident lié</strong> si le conseil fait suite à un incident précis — le motif se pré-remplit alors avec la description de l&#39;incident, modifiable.</li><li>Renseignez le <strong>Motif</strong> du conseil et la <strong>Date de la séance</strong>.</li><li>Composez les <strong>Membres du conseil</strong> : pour chacun, choisissez la personne parmi le personnel et son rôle (<strong>Président</strong>, <strong>Secrétaire</strong> ou <strong>Membre</strong>) ; utilisez <strong>Ajouter un membre</strong> pour en inclure plusieurs.</li><li>Cliquez sur <strong>Enregistrer</strong> — le conseil est créé avec le statut <strong>Convoqué</strong>.</li></ol><p>Sur la page d&#39;un conseil convoqué, vous pouvez encore :</p><ul><li><strong>Modifier</strong> ses informations avant la séance ;</li><li><strong>Annuler le conseil</strong> (avec confirmation, action irréversible) ;</li><li><strong>Supprimer</strong> le conseil (avec confirmation, action irréversible) ;</li><li><strong>Enregistrer la décision</strong> : choisissez la <strong>Décision</strong> — Avertissement, Blâme, Exclusion temporaire, Exclusion définitive ou Non-lieu — et ajoutez si besoin des <strong>Détails de la décision</strong>, puis validez.</li></ul><p>Une fois la décision enregistrée, le conseil passe au statut <strong>Décidé</strong> : la décision et sa date s&#39;affichent, et un bouton <strong>Télécharger le procès-verbal</strong> génère le document correspondant. Un conseil décidé ou annulé ne peut plus être modifié.</p><p>La liste des conseils se filtre par nom d&#39;élève, par classe et par statut (Convoqué, Décidé, Annulé) ; le secrétariat peut consulter et télécharger les procès-verbaux mais ne peut ni créer ni décider un conseil.</p>',12)])])}const v=i(t,[["render",o]]);export{p as __pageData,v as default};
